def renumber_existing_attempts_and_fix_exams(apps, schema_editor):
    ExamAttempt = apps.get_model('assessments', 'ExamAttempt')
    Examination = apps.get_model('assessments', 'Examination')
    
    user_exam_pairs = set(ExamAttempt.objects.values_list('user_id', 'examination_id'))
    for user_id, exam_id in user_exam_pairs:
        attempts = list(ExamAttempt.objects.filter(user_id=user_id, examination_id=exam_id).order_by('started_at', 'id'))
        for idx, att in enumerate(attempts, start=1):
            att.attempt_number = idx
            if att.expires_at and not att.deadline:
                att.deadline = att.expires_at
            att.save(update_fields=['attempt_number', 'deadline'])
            
    Examination.objects.all().update(
        duration_minutes=21,
        total_marks=Decimal('16.00'),
        negative_marking=Decimal('0.25'),
    )


